const c=s=>s._context?.civ||s.world?.settlements[0],known=(s,id)=>c(s)?.discoveries.includes(id),bal=(s,k)=>Object.hasOwn(s.industry,k)?s.industry[k]:s[k];
export const VEHICLES={cart:{speed:180,capacity:32,cost:{wood:48,metal:8},requires:'wheelcraft',facility:'mechanicalLab'},motor:{speed:300,capacity:60,cost:{metal:20,alloy:12,energy:20},requires:'electricity',facility:'mechanicalLab'},biotic:{speed:220,capacity:40,cost:{food:40,wood:20},requires:'bioMobility',facility:'bioticGarden'}};
export const WEAPONS={stone:{power:.7,cost:{wood:6,stone:3},requires:'weaponry'},metal:{power:1.4,cost:{metal:10,fuel:4},requires:'metallurgy'},ballistic:{power:2.5,cost:{alloy:12,energy:10},requires:'ballistics'}};
const can=(s,cost)=>Object.entries(cost).every(([k,v])=>bal(s,k)>=v),pay=(s,cost)=>{for(const [k,v]of Object.entries(cost))if(Object.hasOwn(s.industry,k))s.industry[k]-=v;else s[k]-=v;};
export function equipmentActions(s){const list=[];if(s.buildings.arsenal&&known(s,'weaponry')&&s.weapons.filter(w=>w.condition>0).length<Math.min(128,s.agents.filter(a=>a.alive).length)&&Object.values(WEAPONS).some(w=>known(s,w.requires)&&can(s,w.cost)))list.push('forgeWeapon');if(s.vehicleProject||s.vehicles.filter(v=>v.condition>0).length<Math.min(32,Math.ceil(s.agents.filter(a=>a.alive).length/6))&&Object.values(VEHICLES).some(v=>known(s,v.requires)&&s.buildings[v.facility]&&can(s,v.cost)))list.push('makeVehicle');return list;}
export function equipmentWork(s,a,key,scale,log){if(key==='forgeWeapon'){if(!equipmentActions(s).includes(key))return {reward:-1,energy:1};const [type,spec]=Object.entries(WEAPONS).reverse().find(([,w])=>known(s,w.requires)&&can(s,w.cost));pay(s,spec.cost);s.weapons.push({id:s.nextWeaponId++,type,condition:100,uses:0});s._turn?.allocations.push({purpose:'Senjata '+type,inputs:{...spec.cost}});return {reward:3,energy:8,target:'Senjata '+type};}if(!s.vehicleProject){const option=Object.entries(VEHICLES).reverse().find(([,v])=>known(s,v.requires)&&s.buildings[v.facility]&&can(s,v.cost));if(!option)return {reward:-1,energy:1};const [type,spec]=option;pay(s,spec.cost);s.vehicleProject={type,progress:0,required:40};s._turn?.allocations.push({purpose:'Kendaraan '+type,inputs:{...spec.cost}});}s.vehicleProject.progress=Math.min(40,s.vehicleProject.progress+2*scale);if(s.vehicleProject.progress>=40){const type=s.vehicleProject.type,v=VEHICLES[type];s.vehicles.push({id:s.nextVehicleId++,type,speed:v.speed,capacity:v.capacity,condition:100,uses:0});s.vehicleProject=null;log(s,'Kendaraan '+type+' selesai; dapat mempercepat perjalanan dan membawa muatan lebih banyak.');}return {reward:3,energy:7};}
export function weaponPower(s){s._turn.armed??=new Set();const w=s.weapons.find(w=>w.condition>0&&!s._turn.armed.has(w.id));if(!w)return 0;s._turn.armed.add(w.id);w.uses++;w.condition=Math.max(0,w.condition-1);return WEAPONS[w.type].power;}
